//! The unit sight writer of the fog grid against vectors read from the original `Game.dll` (S20, docs/spec/vision.md
//! section 14). The vectors are generated by `tools/emu/vision_unit_sight_emu.py --rs` (Unicorn runs of `0x6f409e00`,
//! `0x6f409d00`, `0x6f406660`, `0x6f406ab0`); this test needs no game files.

use sim::vision::{SightShape, UnitSightInput, VisionGrid};
use softfloat::F32;

mod vision_unit {
    pub mod vectors {
        include!("vision_unit/vectors.rs");
    }
}
use vision_unit::vectors::{ELEVATION, RADIUS, SHAPES, WRITER};

struct Xs(u32);

impl Xs {
    fn next(&mut self) -> u32 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 17;
        x ^= x << 5;
        self.0 = x;
        x
    }
}

fn fnv64(words: impl Iterator<Item = u64>, width: usize) -> u64 {
    let mut h = 0xCBF2_9CE4_8422_2325u64;
    for v in words {
        for b in 0..width {
            h ^= (v >> (8 * b)) & 0xFF;
            h = h.wrapping_mul(0x1_0000_0001_B3);
        }
    }
    h
}

fn gen_arrays(seed: u32, shift: u32, h: i32, style: u8) -> (Vec<u16>, Vec<u16>, Vec<i16>) {
    let mut rng = Xs(if seed == 0 { 1 } else { seed });
    let pitch = 1i32 << shift;
    let (mut vis, mut msk, mut elev) = (Vec::new(), Vec::new(), Vec::new());
    for i in 0..pitch * h {
        let a = rng.next();
        let b = rng.next();
        let c = rng.next();
        vis.push(if b & 3 == 0 { (a & 0xFFFF) as u16 } else { 0 });
        msk.push(if b & 4 != 0 { (a >> 16) as u16 } else { 0xFFFF });
        let (col, row) = ((i & (pitch - 1)) as u32, (i >> shift) as u32);
        let e: u16 = match style {
            0 => 0,
            1 => ((c % 4) << 7) as u16,
            2 => (((col / 5 + row / 7 + (seed & 3)) % 4) << 7) as u16,
            _ => [0, 0, 128, 256, 384, 1920, 0xFF80, (c & 0xFFFF) as u16][(c % 8) as usize],
        };
        elev.push(e as i16);
    }
    (vis, msk, elev)
}

#[test]
fn shapes_match_the_original_record_for_record() {
    for &(k, count, hash) in SHAPES {
        let s = SightShape::build(k);
        assert_eq!(s.records.len(), count, "record count of radius {k}");
        let words = s.records.iter().flat_map(|r| {
            let p = |v: usize| if v == usize::MAX { -1i32 } else { v as i32 };
            [r.dx as u32 as u64, r.dy as u32 as u64, p(r.a) as u32 as u64, p(r.b) as u32 as u64]
        });
        assert_eq!(fnv64(words, 4), hash, "records of radius {k}");
        assert_eq!(s.n0, 9);
    }
}

#[test]
fn the_elevation_layer_is_the_maximum_cliff_level_of_each_fog_cell() {
    for &(w, h, seed, words) in ELEVATION {
        let mut g = VisionGrid::with_cells(w, h, (F32::ZERO, F32::ZERO), (F32::from_bits(0x3C00_0000), F32::from_bits(0x3C00_0000)));
        g.set_elevation_layer(|x, y| ((x * 131 + y * 197 + seed * 31) % 9) - 2);
        let mut got = Vec::new();
        for r in 0..h {
            for c in 0..w {
                got.push(g.elevation((c, r)) as u16);
            }
        }
        assert_eq!(got, words, "layer of {w}x{h} seed {seed}");
    }
}

#[test]
fn the_radius_conversion_matches_the_original() {
    for &(v, scale, k) in RADIUS {
        let mut g = VisionGrid::with_cells(8, 8, (F32::ZERO, F32::ZERO), (F32::from_bits(scale), F32::from_bits(scale)));
        g.scale = (F32::from_bits(scale), F32::from_bits(scale));
        assert_eq!(g.sight_cells(F32::from_bits(v)), k, "value {v:#x} scale {scale:#x}");
    }
}

#[test]
fn the_unit_writer_matches_the_original_on_every_path() {
    for (n, &(seed, w, h, style, k, mask, owner, ignore, float, a3, a4, px, py, lvl, found, fh, hash)) in
        WRITER.iter().enumerate()
    {
        let mut g = VisionGrid::with_cells(w, h, (F32::ZERO, F32::ZERO), (F32::from_bits(0x3C00_0000), F32::from_bits(0x3C00_0000)));
        let (vis, msk, elev) = gen_arrays(seed, g.shift, h, style);
        g.set_raw_words(vis, msk, elev);
        g.write_unit_sight_cells(&UnitSightInput {
            path_cell: (px, py),
            radius: k,
            mask,
            owner,
            ignore_cliffs: ignore,
            float_move: float,
            float_height: fh,
            terrain_level: lvl,
            ramp_found: found,
            use_radius_four: a3,
            explore_only: a4,
        });
        let (v, m) = g.raw_words();
        let got = fnv64(v.iter().chain(m.iter()).map(|&x| u64::from(x)), 2);
        assert_eq!(got, hash, "writer case {n}: seed {seed} {w}x{h} style {style} k {k} at ({px},{py}) mask {mask:#x}");
    }
}
